 import { NextRequest, NextResponse } from 'next/server';
 import { submissionSchema } from '@/lib/validation';
 import { createStoryEntry } from '@/lib/entries/service';

 export async function POST(request: NextRequest) {
   try {
     let body: unknown;
     try {
       body = await request.json();
     } catch {
       return NextResponse.json(
         {
           success: false,
           error: 'Invalid JSON payload',
         },
         { status: 400 }
       );
     }

     const validationResult = submissionSchema.safeParse(body);

     if (!validationResult.success) {
       const details = validationResult.error.errors.map((err) => ({
         field: err.path.join('.') || 'root',
         message: err.message,
       }));

       return NextResponse.json(
         {
           success: false,
           error: 'Validation failed',
           details,
         },
         { status: 400 }
       );
     }

     const { name, city, contact, story, consent } = validationResult.data;

     // Persist submission to database.
     // In Phase 3, submissions are safely stored with status 'pending_review'
     // awaiting Phase 4 AI moderation.
     await createStoryEntry({
       name,
       city,
       contact,
       story,
       consent,
     });

     // In accordance with Phase 1 status mapping:
     // Non-approved entries (pending_review / rejected) return publicId: null
     // and never leak full story, contact info, internal IDs, or AI diagnostic fields.
     return NextResponse.json(
       {
         success: true,
         status: 'pending_review',
         publicId: null,
         message:
           'Thank you! Your story was received and is under review by our team.',
       },
       { status: 201 }
     );
   } catch (error) {
     // Safe error handling: Log internally without exposing internal errors,
     // stack traces, or credentials to client.
     console.error('Error handling story submission:', error);

     return NextResponse.json(
       {
         success: false,
         error:
           'Unable to process submission at this time. Please try again later.',
       },
       { status: 500 }
     );
   }
 }

