 import { describe, it, before, after } from 'node:test';
 import assert from 'node:assert/strict';
 import prisma from '../lib/db.ts';
 import {
   generatePublicSlug,
   createStoryEntry,
   getPublicEntryBySlug,
   getEntryById,
   updateEntryStatus,
